CREATE INDEX oc_page_events ON oc_events(ordinal,id);
CREATE INDEX oc_page_alerts ON oc_alerts(ordinal,id);
CREATE INDEX oc_page_audit ON oc_audit(ordinal,id);
CREATE INDEX oc_page_intakeSources ON oc_intake_sources(ordinal,id);
CREATE INDEX oc_page_intakeReceipts ON oc_intake_receipts(ordinal,id);
CREATE INDEX oc_lookup_event_identity ON oc_events(json_extract(data,'$.source'),json_extract(data,'$.eventId'));
CREATE INDEX oc_lookup_alert_identity ON oc_alerts(json_extract(data,'$.source'),json_extract(data,'$.key'),json_extract(data,'$.generation'),json_extract(data,'$.service'));
CREATE INDEX oc_lookup_alert_open ON oc_alerts(json_extract(data,'$.source'),json_extract(data,'$.key'),json_extract(data,'$.state'));
CREATE INDEX oc_lookup_receipt_native ON oc_intake_receipts(json_extract(data,'$.source'),json_extract(data,'$.native.eventId'));
CREATE INDEX oc_lookup_receipt_monitoring ON oc_intake_receipts(json_extract(data,'$.source'),json_extract(data,'$.monitoring.eventId'));
CREATE INDEX oc_lookup_receipt_incomplete ON oc_intake_receipts(json_extract(data,'$.source'),json_extract(data,'$.incomplete.sha256'));
CREATE INDEX oc_lookup_receipt_readmission ON oc_intake_receipts(json_extract(data,'$.routing.readmission.receipt'));
CREATE INDEX oc_lookup_receipt_operation ON oc_intake_receipts(json_extract(data,'$.source'),json_extract(data,'$.routing.readmission.operationId'));
CREATE INDEX oc_lookup_receipt_source ON oc_intake_receipts(json_extract(data,'$.source'),ordinal,id);
CREATE INDEX oc_lookup_audit_author ON oc_audit((substr(json_extract(data,'$.actor'),1,7)<>'source:'),ordinal,id);
CREATE INDEX oc_lookup_source_author ON oc_intake_sources((NOT(substr(id,1,7)='native:' AND substr(json_extract(data,'$.name'),1,length('Native incomplete: '))='Native incomplete: ')),ordinal,id);
